window.OL_I18N = {"lang":"sv","dict":{"meta.appName":"Openline eSIM-kompatibilitetstest","meta.searchTitle":"{q} eSIM-kompatibilitet · Openline","ui.skip":"Hoppa till innehåll","ui.brandAria":"Openline — Kontrollera om din enhet är kompatibel","ui.brandSub":"Kontrollera om din enhet är kompatibel","lang.label":"Språk","lang.aria":"Byt språk","hero.titleHtml":"Har din enhet stöd för <span class=\"accent\">eSIM</span>?","hero.tag":"Mobil, surfplatta, smartklocka eller mobil router — skriv in valfritt märke eller modell så ser du direkt om du kan använda Openline på den.","search.placeholder":"Prova ”iPhone 18 Pro”, ”Galaxy Z Fold8”, ”Pixel Watch 5”, ”iPad Air” eller ett modellnummer…","search.aria":"Sök efter varumärke, modell eller modellnummer","search.clear":"Rensa sökning","stats.devices":"enheter","stats.compatible":"kompatibla","stats.notCompatible":"ej kompatibla","stats.brands":"varumärken","filters.label":"Filter","filters.summaryAll":"Alla enheter · Alla varumärken","filters.explain":"Välj kompatibilitetsstatus och/eller ett eller flera varumärken. Filtren kombineras med sökrutan och uppdaterar listan nedan direkt.","filters.compat":"Kompatibilitet","filters.compatAria":"Kompatibilitetsfilter","filters.brands":"Varumärken","filters.brandsAria":"Varumärkesfilter","filters.clearAll":"Rensa alla","filters.compatOnly":"Endast kompatibla","filters.notCompatOnly":"Endast ej kompatibla","filters.allStatuses":"Alla statusar","filters.nBrands":{"one":"{n} varumärke","other":"{n} varumärken"},"filters.matchHtml":{"one":"<strong>{n}</strong> enhet matchar","other":"<strong>{n}</strong> enheter matchar"},"cat.count":{"one":"{n} enhet","other":"{n} enheter"},"results.all":"Alla enheter","results.matching":"Matchande enheter","results.ofTotalHtml":"<strong>{n}</strong> av {total}","results.totalHtml":"totalt <strong>{n}</strong>","results.showingFirst":" · visar de första {max}","legend.ok":"Stöd för eSIM","legend.err":"Endast fysiskt SIM-kort","status.ok":"Kompatibel","status.no":"Ej kompatibel","status.okAria":"eSIM-kompatibel","status.noAria":"Inte eSIM-kompatibel","note.caveatAria":"Regionalt undantag: {note}","popover.aria":"Regionalt undantag","popover.close":"Stäng","empty.noMatchTitle":"Ingen exakt träff.","empty.noMatchBodyHtml":"Prova att bara söka på märket (t.ex. <em>Samsung</em>) eller det exakta modellnumret (t.ex. <em>SM-S921B</em>). Om din enhet är nyare än 2021 och inte är släppt i Kina är chansen mycket stor att den har stöd för eSIM.","empty.bothTitle":"Inga enheter matchar både din sökning och dina filter.","empty.bothBodyHtml":{"one":"Din sökning efter <em>{q}</em> gav totalt <strong>{n}</strong> träff, men den matchar inte dina valda filter. Kanske är det filtren som orsakar konflikten?","other":"Din sökning efter <em>{q}</em> gav totalt <strong>{n}</strong> träffar, men ingen av dem matchar dina valda filter. Kanske är det filtren som orsakar konflikten?"},"empty.filtersTitle":"Inga enheter matchar dina filter.","empty.filtersBody":"Prova att lätta på filtren — att kombinera ovanliga statusar med få varumärken kan ge noll resultat.","empty.nothing":"Inget här ännu.","empty.resetFilters":"Återställ filter","empty.clearSearch":"Rensa sökning","footer.privacy":"Integritet","footer.terms":"Villkor","footer.socialAria":"Openline på sociala medier","footer.onNetwork":"Openline på {network}","footer.handleOnNetwork":"@askopenline på {network}","footer.indexedHtml":"<b id=\"footer-total\">{n}</b> enheter indexerade","region.US":"USA","region.HK":"Hongkong","region.CN":"Fastlandskina","region.KR":"Sydkorea","region.JP":"Japan","region.AU":"Australien","region.TW":"Taiwan","region.SEA":"Sydostasien","region.EU":"Europeiska unionen","region.IN":"Indien","region.UK":"Storbritannien","exp.carrierWatch":"Smartklockor med Cellular får sitt eSIM via ett klockabonnemang från en operatör, som ställs in i den parkopplade mobilens app (Apple Watch-appen, Galaxy Wearable, Pixel Watch-appen). QR-koder för vanliga mobil- eller rese-eSIM kan inte installeras direkt på klockan, så kontrollera att din operatör erbjuder abonnemang för den här klockan.","exp.gpsOnly":"Detta är versionen med enbart GPS. Den saknar mobilmodem och kan inte använda eSIM. GPS + Cellular-versionen av samma klocka har ett annat modellnummer.","exp.cnHkMoDualNano":"iPhone-modeller av denna generation som säljs i Kina, Hongkong och Macao har två fysiska nano-SIM-platser och saknar eSIM. Openline kan inte installeras på dessa enheter. Kontrollera modellnumret under Inställningar › Allmänt › Om.","exp.cnDualNano":"Versionen av denna mobil som säljs i Kina använder två fysiska nano-SIM-kort och saknar eSIM. Modeller som säljs på andra marknader har stöd för eSIM. Kontrollera modellnumret under Inställningar › Allmänt › Om.","exp.cnLocalRules":"Den kinesiska versionen har stöd för eSIM, men kinesiska operatörer aktiverar eSIM endast i butik med ID-kontroll, och utländska eSIM-profiler kan inte installeras när du befinner dig i Kina. Utanför Kina fungerar rese-eSIM som Openline som vanligt.","exp.esimOnlyUsJpCaGulf":"Enheter som säljs i USA, Kanada, Japan, Mexiko och Gulfstaterna saknar SIM-fack och fungerar endast med eSIM. På andra marknader har mobilen även ett nano-SIM-fack, och enheter för Kina kan sakna eSIM. Openline fungerar på alla versioner som har stöd för eSIM.","exp.noSimTray":"Den här versionen saknar fysiskt SIM-fack: alla abonnemang, inklusive Openline, läggs till som eSIM. Du kan spara flera eSIM och växla mellan dem i Inställningar.","exp.iden":"Den här enheten använder Motorolas iDEN-nät (Nextel / Boost push-to-talk), som stängdes ned helt av Sprint i juni 2013. Den kan inte ansluta till något modernt mobilnät — varken med eSIM eller på annat sätt. Endast museiföremål eller samlarobjekt.","exp.cdmaVerizon":"Detta är en enhet med enbart CDMA, byggd för Verizons gamla 2G/3G-CDMA-nät, som stängdes ned den 31 december 2022. Den saknar SIM-plats helt (varken fysisk eller eSIM) — CDMA autentiseras i nätet via enhetens ESN/MEID, inte via SIM. Den kan inte användas med Openline eller någon modern operatör.","exp.cdmaSprint":"Detta är en CDMA-enhet byggd för Sprints gamla nät, som T-Mobile stängde permanent den 31 maj 2022. Nyare Sprint-modeller fick LTE/GSM, men äldre modeller är endast CDMA och kan inte ansluta till något modernt nät — med eller utan eSIM.","exp.sunset":"Den här enheten är beroende av 3G eller äldre 4G-nät som operatörer har stängt ned (AT&T 3G upphörde i februari 2022, T-Mobile i februari 2022, Verizon i december 2022 och de flesta europeiska 3G-nät senast 2025). Även om SIM-facket fungerar finns det i de flesta länder inget nät att ansluta till.","exp.windowsPhone":"Den här enheten kör Windows Phone (eller Windows 10 Mobile), som Microsoft lade ned 2019 — Store, säkerhetsuppdateringar och de flesta egna tjänster är nedstängda. Den saknar eSIM-hårdvara och har i princip inget modernt appstöd. Går inte att använda som vardagsmobil.","exp.kaios":"Detta är en KaiOS-knapptelefon. Nästan inga KaiOS-enheter stöder eSIM — de använder fysiskt SIM-kort (oftast nano-SIM) och riktar sig till billiga marknader för 4G-knapptelefoner som Indien (JioPhone) och Afrika. Openline kan inte installeras här.","exp.telematics":"Detta är en telematikmodul för fordon (Tesla, BMW, Audi m.fl.) med ett eSIM som är fabriksmonterat och fastlött på bilens kommunikationskort. eSIM konfigureras av biltillverkaren på fabriken och kan inte bytas mot en profil som användaren installerar, som Openline. Kan inte servas av användaren.","exp.satellite":"Detta är en satellit-/GPS-kommunikatör (Garmin inReach, SPOT, Zoleo, Iridium GO) som använder satellitnätet Iridium eller Globalstar — inte GSM/LTE. Den kan inte använda eSIM i vanlig mening; uppkopplingen är bunden till ett eget abonnemang hos enhetens tillverkare.","exp.medical":"Detta är ett trygghetslarm (PERS, personal emergency response). Mobilmodemet är låst till tjänsteleverantören (Lively, Medical Guardian, Life Alert, Bay Alarm) och fungerar bara med deras övervakningsabonnemang. Det går inte att installera eSIM från tredje part.","exp.rugged":"Detta är en Samsung Enterprise / Rugged-enhet (Galaxy XCover-serien) avsedd för personal i fält — lager, vård, hotell och restaurang. Den stöder eSIM, men aktiveringen kan styras av arbetsgivarens Samsung Knox MDM-konfiguration. Openline installeras som på vilken vanlig mobil som helst om enheten är olåst.","exp.harmony":"Den här enheten kör HarmonyOS (Huawei) utan Google Mobile Services. eSIM-aktivering kräver vanligtvis Huaweis app för operatörstjänster i EMUI/HarmonyOS. Openline-profiler kan installeras via QR-koden, men aktivering via Google Wallet fungerar inte. Enheter som säljs i Kina kan dessutom avvisa internationella eSIM-profiler på grund av begränsningar i den kinesiska firmwaren.","exp.dualEsimOnly":"Den här varianten stöder två eSIM samtidigt men har inget fysiskt SIM-fack. Openline fungerar — du kan bara inte kombinera det med ett nano-SIM. På vissa regionala versioner kan endast ett eSIM vara aktivt åt gången.","exp.euCarrier":"Vissa europeiska operatörslåsta varianter av den här enheten levererades med eSIM avstängt i firmware. Olåsta/globala modeller har normalt stöd för eSIM. Kontakta din ursprungliga operatör om aktiveringen misslyckas.","exp.usCarrier":"Detta är en variant märkt av en amerikansk operatör (AT&T, T-Mobile, Verizon, Sprint) med låst firmware och ofta operatörsspecifikt bandstöd. eSIM kan vara avstängt eller begränsat till profiler från den operatör som märkt enheten. Olåsta internationella enheter av samma modell fungerar vanligtvis med Openline; operatörsmärkta enheter kanske inte gör det.","exp.verizon":"Verizon-märkta enheter av denna Pixel hade eSIM avstängt vid lanseringen i Verizons nät. Olåsta enheter och enheter från andra operatörer har normalt stöd för eSIM.","exp.googleFi":"På denna Pixel-generation fanns eSIM endast via Google Fi i USA. Andra operatörer använde enbart fysiskt SIM-kort. Globala olåsta enheter har stöd för eSIM överallt.","exp.usEsimOnly":"På denna iPhone köpt i USA har Apple tagit bort det fysiska SIM-facket helt — du måste använda eSIM. I resten av världen har mobilen ett fysiskt SIM-fack utöver eSIM. Openline fungerar i båda fallen.","exp.cnOnly":"Den här enheten levereras med firmware för den kinesiska marknaden. eSIM-stöd finns på pappret, men internationella profiler går ofta inte att aktivera utanför Kina. Om du planerar att resa bör du kontrollera eSIM-aktiveringen med säljaren före köp.","exp.jpDomestic":"Japanska operatörsmärkta mobiler (NTT DoCoMo, au, SoftBank, Rakuten) är oftast bandlåsta till Japans frekvensplan. eSIM-hårdvaran fungerar i Japan; utomlands beror aktiveringen på hur väl banden överlappar med lokala nät.","exp.regionLocked":"Den här enhetens eSIM-aktivering är regionslåst i firmware. Den accepterar endast eSIM-profiler från operatörer i det land eller den region där den såldes.","exp.krOnly":"Den här modellen säljs endast i Sydkorea och använder frekvensband för KT/SKT/LGU+. eSIM-hårdvara finns, men aktivering utomlands är opålitlig.","exp.foldable":"Detta är en vikbar enhet — eSIM finns, men observera att vissa vikbara varianter som säljs i Kina saknar stöd för internationellt eSIM. Kontrollera att modellkoden matchar den globala versionen.","exp.hotspot":"Detta är en bärbar Wi-Fi-hotspot / MiFi-router snarare än en mobil. Den tar emot ett eSIM för att dela mobildata med dina andra enheter. Openline installeras på samma sätt som på en mobil.","exp.simTrayOnly":"Den här enheten har ett mobilmodem men tar endast emot fysiskt nano-SIM eller micro-SIM — det finns inget eSIM-chip. Du kan inte installera Openline som eSIM här; du behöver ett abonnemang med fysiskt SIM-kort.","exp.wifiOnly":"Den här varianten har enbart Wi-Fi — inget mobilmodem. Den kan inte installera något eSIM. Leta efter LTE- / 5G- / Cellular-versionen av samma modell.","exp.ereader":"Detta är en e-läsare med ett fabriksinbyggt mobilmodem kopplat till tillverkarens gratis dataabonnemang (Amazon Whispernet, B&N Nook m.fl.). eSIM/SIM kan inte konfigureras av användaren — du kan inte byta in en Openline-profil.","exp.cellularEsimOnly":"Den här varianten har mobil uppkoppling enbart via eSIM — enheten har inget fysiskt SIM-fack. Openline installeras direkt via QR-kod.","exp.unverifiedVariant":"Våra data kopplar den här modellkoden till mer än en produktfamilj. Det betyder oftast att Apple/Samsung/Google har återanvänt ett internt nummer över flera generationer, eller att en regional version har bytt namn. Openline bör fungera, men om modellnumret på kartongen inte stämmer med enheten du tittar på bör du dubbelkolla med tillverkaren före köp.","exp.crossBrand":"Den här modellkoden förekommer även på en enhet från ett annat varumärke (Vivo/iQOO, Xiaomi/POCO, Nokia/HMD, Nubia/ZTE m.fl.). Det rör sig oftast om ett systervarumärke — hårdvaran är ofta identisk, ibland omärkt — men eSIM-stöd och operatörscertifiering kan skilja sig mellan de två varumärkena. Kontrollera mot din enhets faktiska förpackning.","exp.modelUnverified":"Vi har inget tillförlitligt modell- eller artikelnummer för den här enheten — oftast för att det är en wearable, telematikenhet för fordon, hotspot eller tillbehör vars artikelnummer inte publiceras öppet. eSIM-stöd anges i tillverkarens specifikation, men Openline kan inte matcha en specifik hårdvarukod för att garantera kompatibilitet. Kontrollera med tillverkaren innan du förlitar dig på det.","exp.ambiguous":"Produktnamnet här är mycket kort (”13”, ”F7”, ”M6”…) och lätt att förväxla med modeller med samma nummer från andra varumärken eller generationer. Kontrollera märke och modellkod på din enhet för att säkerställa att posten verkligen stämmer med det du äger.","exp.cnFirmware":"Den här enheten levereras med firmware för den kinesiska marknaden. eSIM-hårdvara finns, men den kinesiska firmwaren blockerar ofta aktivering av internationella eSIM-profiler. Om du vill använda Openline utanför Kina bör du före köp kontrollera med säljaren att firmwaren inte är regionslåst.","exp.regionExcluded":"Enheter av denna modell som säljs i följande regioner levereras utan eSIM-hårdvara, så endast det fysiska SIM-facket fungerar: {regions}. På alla andra marknader stöds eSIM och Openline aktiveras som vanligt. Om du köpt enheten utomlands eller via en parallellimportör bör du jämföra modellnumret med tillverkarens lista.","note.3G free":"Gratis 3G","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"Ej AU/JP/TW","note.Ambiguous name":"Tvetydigt namn","note.CDMA":"CDMA","note.CN firmware":"Kinesisk firmware","note.CN/HK excluded":"Ej CN/HK","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO: dubbla nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN endast dubbla eSIM","note.CN: dual nano-SIM":"CN: dubbla nano-SIM","note.CN: local eSIM rules":"CN: lokala eSIM-regler","note.Carrier watch plan":"Klockabonnemang","note.Cross-brand model code":"Delad modellkod","note.E-reader":"E-läsare","note.Enterprise rugged":"Tålig företagsmodell","note.Foldable":"Vikbar","note.GPS only":"Endast GPS","note.GPS/satellite tracker":"GPS/satellitspårare","note.Google Fi/US only":"Endast Google Fi/US","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"Låst till japanska band","note.KR only":"Endast KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"KaiOS-knapptelefon","note.Medical alert":"Trygghetslarm","note.Mobile hotspot":"Mobil router","note.Model code unverified":"Obekräftad modellkod","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"Ingen eSIM-hårdvara","note.No eSIM in most regions":"Oftast inget eSIM","note.Not on Verizon/Sprint":"Ej på Verizon/Sprint","note.SEA excluded":"Ej SEA","note.SIM tray only":"Endast SIM-fack","note.Sprint":"Sprint","note.US carrier variant":"Amerikansk operatörsvariant","note.US model excluded":"Ej US-modell","note.US variant excluded":"Ej US-variant","note.US/HK excluded":"Ej US/HK","note.US/JP: eSIM ok":"US/JP: eSIM ok","note.US: eSIM only":"US: endast eSIM","note.Unverified variant":"Obekräftad variant","note.Vehicle telematics":"Fordonstelematik","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon US utan eSIM","note.Verizon-only 5G":"Endast Verizon 5G","note.Wi-Fi + Cellular only":"Endast Wi-Fi + Cellular","note.Wi-Fi + free 4G":"Wi-Fi + gratis 4G","note.Wi-Fi only":"Endast Wi-Fi","note.Wi-Fi only in most regions":"Oftast endast Wi-Fi","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"föråldrad","note.dual-eSIM in EU":"dubbla eSIM i EU","note.eSIM only":"Endast eSIM","note.eSIM only (no SIM tray)":"Endast eSIM (inget SIM-fack)","note.eSIM only in US/JP/CA/Gulf":"Endast eSIM i US/JP/CA/Gulf","note.eSIM only via Google Fi":"eSIM endast via Google Fi","note.iDEN":"iDEN","note.sunset":"nedstängt nät"}};
